mapper.select:
SELECT d.submit_time as submitTime, d.name, d.obj_name as equipment, d.source as source,
d.submit_staff as submitStaff,d.state as state,d.result as result
from fault_order d
LEFT JOIN inspect_record_to_business b on b.business_id = d.process_ins_id and b.business_category = 'FAULT'
left join inspect_record r on r.id = b.record_id


        and r.target_id = #{param.objId}


        and r.task_id = #{param.taskId}


        and r.create_time BETWEEN #{param.period.begin} and #{param.period.end}

SELECT d.submit_time as submitTime, d.name, d.obj_name as equipment, d.source as source,
d.submit_staff as submitStaff,d.state as state,d.result as result
from fault_order d
LEFT JOIN inspect_record_to_business b on b.business_id = d.process_ins_id and b.business_category = 'FAULT'
left join inspect_record r on r.id = b.record_id


        and r.target_id = #{param.objId}


        and r.task_id = #{param.taskId}


        and r.create_time BETWEEN #{param.period.begin} and #{param.period.end}

select obj_id as deviceId, count(id) as num, COALESCE(SUM(if(`state` = 'PASS',1,0)),0) as `handler_num`, COALESCE(SUM(if(`state` != 'PASS',1,0)),0) as `un_handler_num` from fault_order
obj_type = 'DEVICE'
and obj_id in
#{id}
and create_time between #{param.period.begin} and #{param.period.end}
group by obj_id
